package plates.core.values

/** What a [PlateSpec] needs of a restriction: a register value it refuses. */
public interface PlateRestriction {
    /** The [PlateTextGroup.key] of the register this restriction watches. */
    public val group: String
    public val reason: String
    public fun matches(groupValue: String): Boolean
}

/** Refused register values, in canonical (storage) form. */
public class ValuesRestriction(override val group: String, public val values: List<String>, override val reason: String) : PlateRestriction {
    override fun matches(groupValue: String): Boolean = groupValue in values
}

/** Thrown by [PlateSpec.checkRestrictions]; the message is the restriction's reason. */
public class PlateRestrictionException(public val restriction: PlateRestriction) : Exception(restriction.reason)
